    TRUE,  -- has_exercise
    'multiple_choice',  -- exercise_type
    '[{"question_id":1,"question":"____ somebody The baby had been abandoned by its mother.","options":["abandon","abet","adequate","abstemious"],"answer":"abandon","hint":"bỏ rơi, ruồng bỏ","explanation":"abandon: bỏ rơi, ruồng bỏ"},{"question_id":2,"question":"This tax should be ____.","options":["abolish","artificial","adolescent","analogy"],"answer":"abolish","hint":"cancel, revoke","explanation":"abolish: cancel, revoke"},{"question_id":3,"question":"I''ve joined a class for ____ beginners.","options":["absolute","acquisition","accommodate","attribute"],"answer":"absolute","hint":"hoàn toàn","explanation":"absolute: hoàn toàn"},{"question_id":4,"question":"____ something Plants absorb carbon dioxide from the air.","options":["automatic","appeal","alter","absorb"],"answer":"absorb","hint":"suck up; take up, take in","explanation":"absorb: suck up; take up, take in"},{"question_id":5,"question":"____ knowledge/principles","options":["accommodate","anticipate","affluent","abstract"],"answer":"abstract","hint":"lý thuyết, trừu tượng","explanation":"abstract: lý thuyết, trừu tượng"},{"question_id":6,"question":"That uniform makes the guards look ____.","options":["automatic","abhor","artificial","absurd"],"answer":"absurd","hint":"ngớ ngẩn, lố bịch","explanation":"absurd: ngớ ngẩn, lố bịch"},{"question_id":7,"question":"High-speed internet ____ has become a necessity.","options":["abandon","adjust","adversary","access"],"answer":"access","hint":"tiếp cận, sử dụng","explanation":"access: tiếp cận, sử dụng"},{"question_id":8,"question":"The hotel can ____ up to 500 guests.","options":["advocate","absolute","attribute","accommodate"],"answer":"accommodate","hint":"host guests; provide lodging; adapt oneself; give, bestow","explanation":"accommodate: host guests; provide lodging; adapt oneself; give, bestow"},{"question_id":9,"question":"____ somebody/something + adv./prep. His wife accompanied him on the trip.","options":["accompany","advent","alternative","absorb"],"answer":"accompany","hint":"đồng hành, đi cùng, hộ tống","explanation":"accompany: đồng hành, đi cùng, hộ tống"},{"question_id":10,"question":"They questioned the ____ of the information in the file.","options":["abandon","alacrity","acclaim","accuracy"],"answer":"accuracy","hint":"preciseness, exactness","explanation":"accuracy: preciseness, exactness"},{"question_id":11,"question":"____ somebody of something to accuse somebody of murder/a crime","options":["accuse","accolade","attitude","assert"],"answer":"accuse","hint":"buộc tội, tố cáo","explanation":"accuse: buộc tội, tố cáo"},{"question_id":12,"question":"Fill in the blank: thu được, đạt được = ____","options":["acquire","anonymous","arbitrary","attribute"],"answer":"acquire","hint":"thu được, đạt được","explanation":"acquire: thu được, đạt được"},{"question_id":13,"question":"theories of child language ____","options":["alternative","acquisition","atmosphere","access"],"answer":"acquisition","hint":"sự giành được, thu được, đạt được (kiến thức, kĩ năng)","explanation":"acquisition: sự giành được, thu được, đạt được (kiến thức, kĩ năng)"},{"question_id":14,"question":"Fill in the blank: kích hoạt = ____","options":["activate","abet","aforementioned","abridge"],"answer":"activate","hint":"kích hoạt","explanation":"activate: kích hoạt"},{"question_id":15,"question":"There is an ____ shortage of water.","options":["acute","accord","analyse","absolute"],"answer":"acute","hint":"nhanh nhạy, sắc sảo","explanation":"acute: nhanh nhạy, sắc sảo"},{"question_id":16,"question":"It''s amazing how soon you ____.","options":["affable","anonymous","aesthetic","adapt"],"answer":"adapt","hint":"thích nghi (với môi trường...)","explanation":"adapt: thích nghi (với môi trường...)"},{"question_id":17,"question":"What''s your name and ____?","options":["alacrity","adversity","address","affable"],"answer":"address","hint":"phân tích và đề xuất cách giải quyết một vấn đề nào đó","explanation":"address: phân tích và đề xuất cách giải quyết một vấn đề nào đó"},{"question_id":18,"question":"They''ll need an ____ supply of hot water.","options":["accompany","affable","adequate","aesthetic"],"answer":"adequate","hint":"đủ, đầy đủ","explanation":"adequate: đủ, đầy đủ"},{"question_id":19,"question":"Once in the bloodstream, the bacteria ____ to the surface of the red cells.","options":["adhere","attitude","anticipate","acquisition"],"answer":"adhere","hint":"stick to, cling to; be devoted to (an idea, group, etc.)","explanation":"adhere: stick to, cling to; be devoted to (an idea, group, etc.)"},{"question_id":20,"question":"The planes landed on ____ runways.","options":["adjacent","aforementioned","accuse","attribute"],"answer":"adjacent","hint":"kế bên, gần","explanation":"adjacent: kế bên, gần"},{"question_id":21,"question":"____ something Watch out for sharp bends and adjust your speed accordingly.","options":["alacrity","adjust","advent","attribute"],"answer":"adjust","hint":"điều chỉnh, làm cho thích hợp","explanation":"adjust: điều chỉnh, làm cho thích hợp"},{"question_id":22,"question":"____ between the ages of 13 and 18 and the problems they face","options":["adolescent","accommodate","anticipate","analyse"],"answer":"adolescent","hint":"thanh niên","explanation":"adolescent: thanh niên"},{"question_id":23,"question":"a campaign to encourage childless couples to ____","options":["adopt","adhere","assignment","adapt"],"answer":"adopt","hint":"áp dụng (một phương pháp, một cách nhìn mới, ...)","explanation":"adopt: áp dụng (một phương pháp, một cách nhìn mới, ...)"},{"question_id":24,"question":"____ for something/somebody an advocate for hospital workers","options":["adhere","advocate","alternative","abrogate"],"answer":"advocate","hint":"ủng hộ, tán thành","explanation":"advocate: ủng hộ, tán thành"},{"question_id":25,"question":"the ____ appeal of the songs","options":["aesthetic","adequate","abet","accolade"],"answer":"aesthetic","hint":"(thuộc) mỹ học, thẩm mỹ","explanation":"aesthetic: (thuộc) mỹ học, thẩm mỹ"},{"question_id":26,"question":"How will these changes ____ us?","options":["allocate","affect","acquisition","accord"],"answer":"affect","hint":"ảnh hưởng đến, tác động đến","explanation":"affect: ảnh hưởng đến, tác động đến"},{"question_id":27,"question":"____ something (for something) A large sum has been allocated for buying new books for the library.","options":["allocate","accommodate","abandon","activate"],"answer":"allocate","hint":"ration; allot, set aside; designate a portion of system resources for a particular task or operation (Computers)","explanation":"allocate: ration; allot, set aside; designate a portion of system resources for a particular task or operation (Computers)"},{"question_id":28,"question":"Prices have not ____ significantly this year.","options":["adversary","acumen","accompany","alter"],"answer":"alter","hint":"thay đổi; làm cho cái gì đó thay đổi","explanation":"alter: thay đổi; làm cho cái gì đó thay đổi"},{"question_id":29,"question":"The road was closed so we had to find an ____ route.","options":["adequate","appropriate","acute","alternative"],"answer":"alternative","hint":"sự lựa chọn","explanation":"alternative: sự lựa chọn"},{"question_id":30,"question":"____ (between A and B) The teacher drew an analogy between the human heart and a pump.","options":["abstract","adjacent","adapt","analogy"],"answer":"analogy","hint":"sự so sánh những đặc điểm tương tự; sự tương tự, sự giống nhau","explanation":"analogy: sự so sánh những đặc điểm tương tự; sự tương tự, sự giống nhau"},{"question_id":31,"question":"____ something The job involves collecting and analysing data.","options":["analyse","abhor","authentic","affluent"],"answer":"analyse","hint":"phân tích","explanation":"analyse: phân tích"},{"question_id":32,"question":"an ____ donor","options":["alter","abandon","artificial","anonymous"],"answer":"anonymous","hint":"giấu tên, ẩn danh","explanation":"anonymous: giấu tên, ẩn danh"},{"question_id":33,"question":"____ something We don''t anticipate any major problems.","options":["anticipate","alternative","acquisition","acute"],"answer":"anticipate","hint":"đoán trước, liệu trước","explanation":"anticipate: đoán trước, liệu trước"},{"question_id":34,"question":"a piece of laboratory ____","options":["adhere","abstemious","apparatus","adolescent"],"answer":"apparatus","hint":"dụng cụ, thiết bị cho một hoạt động","explanation":"apparatus: dụng cụ, thiết bị cho một hoạt động"},{"question_id":35,"question":"____ for something to launch a TV appeal for donations to the charity","options":["appeal","aggravate","atmosphere","accord"],"answer":"appeal","hint":"hấp dẫn, lôi cuốn","explanation":"appeal: hấp dẫn, lôi cuốn"},{"question_id":36,"question":"Spending the holidays in Britain wasn''t a prospect that I found particularly ____.","options":["agitate","acquisition","absurd","appealing"],"answer":"appealing","hint":"hấp dẫn, thú vị","explanation":"appealing: hấp dẫn, thú vị"},{"question_id":37,"question":"He suffered from headaches and loss of ____.","options":["appetite","agitate","abrupt","assist"],"answer":"appetite","hint":"desire, hunger","explanation":"appetite: desire, hunger"},{"question_id":38,"question":"Over the years he came to ____ the beauty and tranquillity of the river.","options":["absurd","abolish","abstract","appreciate"],"answer":"appreciate","hint":"tăng giá trị/lên giá (hàng hoá...) theo thời gian","explanation":"appreciate: tăng giá trị/lên giá (hàng hoá...) theo thời gian"},{"question_id":39,"question":"an ____ response/measure/method","options":["adhere","anonymous","abridge","appropriate"],"answer":"appropriate","hint":"thích hợp, thích đáng","explanation":"appropriate: thích hợp, thích đáng"},{"question_id":40,"question":"The choice of players for the team seemed completely ____.","options":["arbitrary","authentic","activate","acrimonious"],"answer":"arbitrary","hint":"wanton, reckless; uncontrolled, unrestricted; unreasonable, unsupported","explanation":"arbitrary: wanton, reckless; uncontrolled, unrestricted; unreasonable, unsupported"},{"question_id":41,"question":"She struggled to ____ her thoughts.","options":["allocate","admonish","articulate","absurd"],"answer":"articulate","hint":"diễn đạt suy nghĩ/cảm xúc một cách rõ ràng bằng lời","explanation":"articulate: diễn đạt suy nghĩ/cảm xúc một cách rõ ràng bằng lời"},{"question_id":42,"question":"an ____ limb/flower/sweetener/fertilizer","options":["acclaim","adversity","advent","artificial"],"answer":"artificial","hint":"not genuine, simulated","explanation":"artificial: not genuine, simulated"},{"question_id":43,"question":"____ of something The book aims to cover all aspects of city life.","options":["aspect","atmosphere","abet","articulate"],"answer":"aspect","hint":"point of view, facet; appearance, outlook; direction; action of a verb without relating to its time","explanation":"aspect: point of view, facet; appearance, outlook; direction; action of a verb without relating to its time"},{"question_id":44,"question":"____ that… She continued to assert that she was innocent.","options":["absorb","assert","accede","adolescent"],"answer":"assert","hint":"state, declare; insist on","explanation":"assert: state, declare; insist on"},{"question_id":45,"question":"____ somebody/something Accurately assessing environmental impacts is very complex.","options":["assess","accommodate","appealing","acrimonious"],"answer":"assess","hint":"đánh giá","explanation":"assess: đánh giá"},{"question_id":46,"question":"In his job, patience is an invaluable ____.","options":["accommodate","affect","attitude","asset"],"answer":"asset","hint":"của cải, tài sản","explanation":"asset: của cải, tài sản"},{"question_id":47,"question":"Students are required to complete all homework ____.","options":["affable","articulate","absorb","assignment"],"answer":"assignment","hint":"task, mission; transfer of ownership or rights","explanation":"assignment: task, mission; transfer of ownership or rights"},{"question_id":48,"question":"Anyone willing to ____ can contact this number.","options":["absorb","adapt","assist","aspect"],"answer":"assist","hint":"giúp đỡ, hỗ trợ","explanation":"assist: giúp đỡ, hỗ trợ"},{"question_id":49,"question":"____ somebody/something with somebody/something I always associate the smell of baking with my childhood.","options":["associate","absorb","analyse","aesthetic"],"answer":"associate","hint":"gắn kết, kết nối (những ý nghĩ về người hoặc vật)","explanation":"associate: gắn kết, kết nối (những ý nghĩ về người hoặc vật)"},{"question_id":50,"question":"to seek/apply for/be granted ____","options":["acclaim","adjust","asylum","adolescent"],"answer":"asylum","hint":"shelter, refuge; hospital for the mentally ill","explanation":"asylum: shelter, refuge; hospital for the mentally ill"},{"question_id":51,"question":"Wind power doesn''t release carbon dioxide into the ____.","options":["abandon","associate","assist","atmosphere"],"answer":"atmosphere","hint":"bầu không khí (nghĩa bóng)","explanation":"atmosphere: bầu không khí (nghĩa bóng)"},{"question_id":52,"question":"____ towards somebody/something These societies have to change their attitudes towards women.","options":["activate","accolade","artificial","attitude"],"answer":"attitude","hint":"thái độ, quan điểm","explanation":"attitude: thái độ, quan điểm"},{"question_id":53,"question":"Patience is one of the most important ____ in a teacher.","options":["accentuate","assist","attribute","associate"],"answer":"attribute","hint":"đức tính, đặc tính","explanation":"attribute: đức tính, đặc tính"},{"question_id":54,"question":"I don''t know if the painting is ____.","options":["adversity","authentic","accommodate","accuracy"],"answer":"authentic","hint":"đích thực; xác thực","explanation":"authentic: đích thực; xác thực"},{"question_id":55,"question":"____ doors","options":["advocate","abandon","automatic","appealing"],"answer":"automatic","hint":"operating by itself; unintentional","explanation":"automatic: operating by itself; unintentional"},{"question_id":56,"question":"a campaign in Wales for greater ____","options":["automatic","affable","autonomy","assignment"],"answer":"autonomy","hint":"independence","explanation":"autonomy: independence"},{"question_id":57,"question":"Fill in the blank: xúi giục = ____","options":["adjust","abet","aggravate","aesthetic"],"answer":"abet","hint":"xúi giục","explanation":"abet: xúi giục"},{"question_id":58,"question":"I ____ all forms of racism.","options":["abhor","asset","abandon","attitude"],"answer":"abhor","hint":"ghê tởm; ghét cay ghét đắng","explanation":"abhor: ghê tởm; ghét cay ghét đắng"},{"question_id":59,"question":"____ poverty/misery/failure","options":["accommodate","abject","acquisition","abolish"],"answer":"abject","hint":"khốn khổ và hết hy vọng","explanation":"abject: khốn khổ và hết hy vọng"},{"question_id":60,"question":"She has been asked to ____ the novel for radio.","options":["acquisition","asset","abridge","absorb"],"answer":"abridge","hint":"rút ngắn lại, cắt bớt (sách, vở kịch,...)","explanation":"abridge: rút ngắn lại, cắt bớt (sách, vở kịch,...)"},{"question_id":61,"question":"Fill in the blank: bãi bỏ (luật lệ, thỏa thuận,...) = ____","options":["assist","abandon","anonymous","abrogate"],"answer":"abrogate","hint":"bãi bỏ (luật lệ, thỏa thuận,...)","explanation":"abrogate: bãi bỏ (luật lệ, thỏa thuận,...)"},{"question_id":62,"question":"an ____ change/halt/departure","options":["accord","adversity","accede","abrupt"],"answer":"abrupt","hint":"bất ngờ, đột ngột (một cách khó chịu)","explanation":"abrupt: bất ngờ, đột ngột (một cách khó chịu)"},{"question_id":63,"question":"He was a hard-working man with ____ habits.","options":["apparatus","advocate","abstract","abstemious"],"answer":"abstemious","hint":"tiết chế, có điều độ","explanation":"abstemious: tiết chế, có điều độ"},{"question_id":64,"question":"Fill in the blank: đồng ý, tán thành một ý kiến, đề nghị,... = ____","options":["allocate","adversary","accede","address"],"answer":"accede","hint":"đồng ý, tán thành một ý kiến, đề nghị,...","explanation":"accede: đồng ý, tán thành một ý kiến, đề nghị,..."},{"question_id":65,"question":"Fill in the blank: tô điểm, làm nổi bật = ____","options":["authentic","accentuate","acumen","abrupt"],"answer":"accentuate","hint":"tô điểm, làm nổi bật","explanation":"accentuate: tô điểm, làm nổi bật"},{"question_id":66,"question":"a highly/widely ____ performance","options":["acclaim","appealing","abstemious","adequate"],"answer":"acclaim","hint":"ca ngợi, tán dương","explanation":"acclaim: ca ngợi, tán dương"},{"question_id":67,"question":"There is no higher ____ at this school than an honorary degree.","options":["artificial","accolade","abrogate","adhere"],"answer":"accolade","hint":"sự vinh danh/phần thưởng cho thành tựu mà mọi người ngưỡng mộ","explanation":"accolade: sự vinh danh/phần thưởng cho thành tựu mà mọi người ngưỡng mộ"},{"question_id":68,"question":"The two sides signed a peace ____ last July.","options":["abridge","accord","atmosphere","acclaim"],"answer":"accord","hint":"hiệp định, hiệp ước","explanation":"accord: hiệp định, hiệp ước"},{"question_id":69,"question":"His parents went through an ____ divorce.","options":["acrimonious","anonymous","artificial","abrogate"],"answer":"acrimonious","hint":"chua cay, gay gắt","explanation":"acrimonious: chua cay, gay gắt"},{"question_id":70,"question":"business/commercial/financial ____","options":["acumen","abstract","asylum","abandon"],"answer":"acumen","hint":"sự nhạy bén","explanation":"acumen: sự nhạy bén"},{"question_id":71,"question":"She was ____ for chewing gum in class.","options":["acquisition","absurd","advent","admonish"],"answer":"admonish","hint":"khiển trách, la rầy","explanation":"admonish: khiển trách, la rầy"},{"question_id":72,"question":"the ____ of new technology","options":["abstract","absurd","advent","aesthetic"],"answer":"advent","hint":"sự ra đời, sự xuất hiện","explanation":"advent: sự ra đời, sự xuất hiện"},{"question_id":73,"question":"his old political ____","options":["acrimonious","adapt","activate","adversary"],"answer":"adversary","hint":"đối thủ","explanation":"adversary: đối thủ"},{"question_id":74,"question":"courage in the face of ____","options":["advent","adversity","accommodate","abandon"],"answer":"adversity","hint":"nghịch cảnh","explanation":"adversity: nghịch cảnh"},{"question_id":75,"question":"He struck me as an ____ sort of a man.","options":["affable","analyse","advent","acquire"],"answer":"affable","hint":"hoà nhã, dễ gần","explanation":"affable: hoà nhã, dễ gần"},{"question_id":76,"question":"____ Western countries","options":["affluent","acumen","acute","access"],"answer":"affluent","hint":"giàu có","explanation":"affluent: giàu có"},{"question_id":77,"question":"The ____ person was seen acting suspiciously.","options":["aforementioned","accede","associate","assist"],"answer":"aforementioned","hint":"đã kể trước đây, đã nói ở trên","explanation":"aforementioned: đã kể trước đây, đã nói ở trên"},{"question_id":78,"question":"Pollution can ____ asthma.","options":["assert","accommodate","arbitrary","aggravate"],"answer":"aggravate","hint":"làm trầm trọng thêm, làm nặng thêm","explanation":"aggravate: làm trầm trọng thêm, làm nặng thêm"},{"question_id":79,"question":"Fill in the blank: tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội) = ____","options":["agitate","aesthetic","adapt","accuse"],"answer":"agitate","hint":"tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội)","explanation":"agitate: tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội)"},{"question_id":80,"question":"They accepted the offer with ____.","options":["articulate","apparatus","adjacent","alacrity"],"answer":"alacrity","hint":"sự sốt sắng","explanation":"alacrity: sự sốt sắng"}]',  -- exercise_data (JSON)
    120,  -- exercise_duration (ước tính: 1.5 phút/câu)
    60,  -- pass_score (60%)
    80,  -- max_score (1 điểm/câu)
    FALSE,  -- is_free
    TRUE,  -- is_active
    0,  -- view_count
    NOW(),
    NOW()
);

-- Kiểm tra kết quả
SELECT 
    lesson_id,
    module_id,
    course_id,
    title,
    lesson_type,
    exercise_type,
    has_exercise,
    JSON_LENGTH(exercise_data) as total_questions,
    max_score,
    pass_score
FROM lessons 
WHERE lesson_id = 71;
